-- NDMO Data Governance - PostgreSQL seed (auto-generated, synthetic data)
SET client_encoding = 'UTF8';
BEGIN;

DROP TABLE IF EXISTS raw_vendors CASCADE;
CREATE TABLE raw_vendors ("vendor_id" TEXT, "vendor_name_ar" TEXT, "cr_number" TEXT, "vat_number" TEXT, "city" TEXT, "contact_person_ar" TEXT, "contact_email" TEXT, "contact_phone" TEXT, "iban" TEXT, "status" TEXT, "last_updated" TEXT);

DROP TABLE IF EXISTS raw_invoices CASCADE;
CREATE TABLE raw_invoices ("invoice_no" TEXT, "vendor_id" TEXT, "issue_date" TEXT, "currency" TEXT, "subtotal" TEXT, "vat_amount" TEXT, "total_amount" TEXT, "cost_center" TEXT, "approved_by_id" TEXT, "payment_iban" TEXT);

DROP TABLE IF EXISTS raw_employees CASCADE;
CREATE TABLE raw_employees ("employee_id" TEXT, "full_name_ar" TEXT, "national_id" TEXT, "department" TEXT, "job_title" TEXT, "monthly_salary_sar" TEXT, "bank_iban" TEXT, "mobile" TEXT, "biometric_on_file" TEXT, "hire_date" TEXT);

DROP TABLE IF EXISTS raw_citizen_requests CASCADE;
CREATE TABLE raw_citizen_requests ("request_id" TEXT, "submitted_date" TEXT, "channel" TEXT, "request_text_ar" TEXT, "status" TEXT, "priority" TEXT);

DROP TABLE IF EXISTS raw_documents CASCADE;
CREATE TABLE raw_documents ("doc_id" TEXT, "title_ar" TEXT, "snippet_ar" TEXT, "author_dept" TEXT, "created_date" TEXT, "current_label" TEXT);

DROP TABLE IF EXISTS raw_open_datasets CASCADE;
CREATE TABLE raw_open_datasets ("record_id" TEXT, "entity_name_ar" TEXT, "cr_number" TEXT, "main_activity" TEXT, "city" TEXT, "registration_status" TEXT, "dataset_source" TEXT, "license" TEXT);

DROP TABLE IF EXISTS data_dictionary CASCADE;
CREATE TABLE data_dictionary ("source_file" TEXT, "field" TEXT, "data_type" TEXT, "contains_pii" TEXT, "ndmo_level" TEXT, "impact_category" TEXT, "detection_method" TEXT, "notes" TEXT);

DROP TABLE IF EXISTS ground_truth_labels CASCADE;
CREATE TABLE ground_truth_labels ("source_file" TEXT, "record_id" TEXT, "ndmo_level" TEXT, "impact_category" TEXT, "recommended_detection" TEXT, "rationale" TEXT);

DROP TABLE IF EXISTS quality_issues_log CASCADE;
CREATE TABLE quality_issues_log ("file" TEXT, "row_id" TEXT, "column" TEXT, "dq_dimension" TEXT, "defect_type" TEXT, "description" TEXT);

COMMIT;
